-- ============================================================================
-- Sponsorship Growth Platform — Stage 4 reference data
-- File: db/09_reference_registers_part1of5.sql   (generated by build_registers.py from the analysis repository; do not hand-edit)
-- Purpose: Source register (135), festival benchmarks (103), 7 non-approved catalogue scenarios (labelled analysis/option), and the read-only `ref` library of every current repository dataset.
-- Run in the Supabase SQL Editor as the project owner, after 01–08. Refuses to run twice.
-- Adds rows only: no existing row, approved number, metric or definition is changed.
-- ============================================================================
BEGIN;
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM public.import_batch WHERE import_batch_id = 'IB-REF-SOURCES') THEN
        RAISE EXCEPTION 'This file is already loaded (import batch IB-REF-SOURCES exists). Nothing was changed.';
    END IF;
END $$;
-- Read-only reference library: every current dataset of the analysis repository, verbatim.
CREATE SCHEMA IF NOT EXISTS ref;
CREATE TABLE IF NOT EXISTS ref.dataset (
    dataset_id      TEXT PRIMARY KEY,
    title           TEXT NOT NULL,
    source_path     TEXT NOT NULL,
    sheet           TEXT,
    record_class    TEXT NOT NULL CHECK (record_class IN ('historical_synthetic', 'external_research', 'model_output',
                        'model_assumption', 'operating_plan', 'evaluation', 'documentation')),
    status          TEXT NOT NULL,
    ai_visible      BOOLEAN NOT NULL,
    row_count       INTEGER NOT NULL CHECK (row_count >= 0),
    columns         JSONB NOT NULL,
    source_sha256   TEXT NOT NULL,
    note            TEXT,
    import_batch_id TEXT NOT NULL REFERENCES public.import_batch(import_batch_id),
    loaded_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS ref.dataset_row (
    dataset_id  TEXT NOT NULL REFERENCES ref.dataset(dataset_id),
    row_no      INTEGER NOT NULL CHECK (row_no >= 1),
    data        JSONB NOT NULL,
    PRIMARY KEY (dataset_id, row_no)
);
CREATE INDEX IF NOT EXISTS dataset_row_data_gin ON ref.dataset_row USING gin (data jsonb_path_ops);
-- Rows are immutable once loaded.
CREATE OR REPLACE FUNCTION ref.tg_block_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'ref.% is read-only reference data.', TG_TABLE_NAME USING ERRCODE = '42501'; END $$;
DROP TRIGGER IF EXISTS tg_ref_dataset_ro ON ref.dataset;
CREATE TRIGGER tg_ref_dataset_ro BEFORE UPDATE OR DELETE ON ref.dataset FOR EACH ROW EXECUTE FUNCTION ref.tg_block_change();
DROP TRIGGER IF EXISTS tg_ref_row_ro ON ref.dataset_row;
CREATE TRIGGER tg_ref_row_ro BEFORE UPDATE OR DELETE ON ref.dataset_row FOR EACH ROW EXECUTE FUNCTION ref.tg_block_change();
-- Access: the app reads only; the browser roles get nothing.
REVOKE ALL ON SCHEMA ref FROM PUBLIC;
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN EXECUTE 'REVOKE ALL ON SCHEMA ref FROM anon'; EXECUTE 'REVOKE ALL ON ALL TABLES IN SCHEMA ref FROM anon'; END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN EXECUTE 'REVOKE ALL ON SCHEMA ref FROM authenticated'; EXECUTE 'REVOKE ALL ON ALL TABLES IN SCHEMA ref FROM authenticated'; END IF;
END $$;
GRANT USAGE ON SCHEMA ref TO app_service;
GRANT SELECT ON ref.dataset, ref.dataset_row TO app_service;
COMMIT;
